<?php

namespace App\Services\Evidence;

use Carbon\Carbon;
use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Facades\Http;
use Illuminate\Support\Facades\Log;

/**
 * Fetches real documents from authoritative sources.
 *
 * Every title, URL, date and passage returned here is read from the remote
 * document. Nothing in a source record is generated by a language model.
 * Only short search terms leave the server, never the user's own text.
 */
class EvidenceRetriever
{
    private const TIMEOUT = 15;

    /** @var string[] Providers that failed during the last retrieve() call. */
    private array $failures = [];

    /**
     * @param  array{drugs?:string[],topics?:string[],keywords?:string[]} $terms
     * @return array<int,array<string,mixed>> Sources ordered by authority tier, ids S1..Sn
     */
    public function retrieve(array $terms): array
    {
        $this->failures = [];

        $drugs    = array_slice($this->clean($terms['drugs'] ?? []), 0, 5);
        $topics   = array_slice($this->clean($terms['topics'] ?? []), 0, 3);
        $keywords = array_merge($drugs, $topics, $this->clean($terms['keywords'] ?? []));

        $documents = [];
        foreach ($drugs as $drug) {
            $documents[] = $this->safely('openFDA', fn () => $this->drugLabel($drug));
        }
        foreach ($this->whoSlugs(array_merge($topics, $drugs)) as $slug) {
            $documents[] = $this->safely('WHO', fn () => $this->whoFactSheet($slug));
        }
        foreach (array_slice($topics ?: $drugs, 0, 2) as $topic) {
            $documents[] = $this->safely('MedlinePlus', fn () => $this->healthTopic($topic));
        }
        if ($topics || $drugs) {
            $query = array_values(array_filter([$drugs[0] ?? null, $topics[0] ?? null]));
            $reviews = $this->safely('PubMed', fn () => $this->systematicReviews($query));
            array_push($documents, ...($reviews ?? []));
        }

        $unique = [];
        foreach (array_filter($documents) as $doc) {
            $unique[$doc['url']] ??= $doc;
        }
        $documents = array_values($unique);
        usort($documents, fn ($a, $b) => $this->tier($a['type']) <=> $this->tier($b['type']));

        $sources = [];
        foreach (array_slice($documents, 0, config('evidence.max_sources')) as $i => $doc) {
            $sources[] = [
                'id'        => 'S' . ($i + 1),
                'type'      => $doc['type'],
                'tier'      => $this->tier($doc['type']),
                'title'     => $doc['title'],
                'publisher' => $doc['publisher'],
                'url'       => $doc['url'],
                'date'      => $doc['date'],
                'date_kind' => $doc['date_kind'],
                'stale'     => $this->isStale($doc['type'], $doc['date']),
                'passage'   => $this->selectPassage($doc['text'], $keywords),
                'text'      => $doc['text'],
            ];
        }

        return $sources;
    }

    /** Re-pick each source's excerpt to match the wording of the claims. */
    public function focus(array $sources, array $claimTexts): array
    {
        preg_match_all('/[a-z]{5,}|\d{2,}/', mb_strtolower(implode(' ', $claimTexts)), $m);
        $words = array_values(array_unique($m[0]));

        return array_map(
            fn ($s) => ['passage' => $this->selectPassage($s['text'], $words)] + $s,
            $sources
        );
    }

    /** @return string[] */
    public function failures(): array
    {
        return array_values(array_unique($this->failures));
    }

    private function drugLabel(string $drug): ?array
    {
        $base = preg_replace('/ (hydrochloride|hcl|sodium|potassium|calcium|besylate|maleate|succinate|tartrate|sulfate)$/', '', $drug);
        $name = config('evidence.drug_synonyms')[$base] ?? $base;

        return $this->remember("label_{$name}", function () use ($name) {
            // Labels are large, so ask only for exact single-ingredient matches.
            $names = array_map(
                fn ($salt) => '"' . strtoupper(trim("{$name} {$salt}")) . '"',
                ['', 'hydrochloride', 'hcl', 'sodium', 'potassium', 'calcium', 'besylate', 'maleate', 'succinate', 'tartrate', 'sulfate', 'propionate']
            );
            $match = 'openfda.generic_name.exact:(' . implode(' ', $names) . ')';

            $label = null;
            // Prescription labels (full interaction data) first, then any label.
            foreach (["{$match} AND _exists_:drug_interactions", $match] as $search) {
                $response = Http::timeout(self::TIMEOUT)->get('https://api.fda.gov/drug/label.json', [
                    'search' => $search, 'sort' => 'effective_time:desc', 'limit' => 2,
                ]);
                // openFDA answers 404 when nothing matches.
                if ($response->status() === 404) {
                    continue;
                }
                $response->throw();
                $label = collect($response->json('results', []))->first(fn ($r) => !empty($r['set_id']));
                if ($label) {
                    break;
                }
            }

            if (!$label) {
                return null;
            }

            $text = [];
            foreach ([
                'boxed_warning', 'indications_and_usage', 'purpose', 'dosage_and_administration',
                'contraindications', 'do_not_use', 'warnings', 'warnings_and_cautions', 'drug_interactions',
                'ask_doctor', 'ask_doctor_or_pharmacist', 'stop_use', 'adverse_reactions',
                'pregnancy_or_breast_feeding', 'clinical_pharmacology', 'mechanism_of_action',
            ] as $section) {
                if (!empty($label[$section])) {
                    $text[] = implode(' ', (array) $label[$section]);
                }
            }

            return [
                'type'      => 'drug_label',
                'title'     => ucwords(strtolower($label['openfda']['generic_name'][0])) . ' prescribing label'
                    . (isset($label['openfda']['manufacturer_name'][0]) ? " ({$label['openfda']['manufacturer_name'][0]})" : ''),
                'publisher' => 'U.S. Food and Drug Administration / DailyMed',
                'url'       => 'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=' . rawurlencode($label['set_id']),
                'date'      => $this->date($label['effective_time'] ?? null),
                'date_kind' => 'effective',
                'text'      => $this->plain(implode("\n", $text)),
            ];
        });
    }

    private function healthTopic(string $topic): ?array
    {
        return $this->remember("topic_{$topic}", function () use ($topic) {
            $response = Http::timeout(self::TIMEOUT)->get('https://wsearch.nlm.nih.gov/ws/query', [
                'db' => 'healthTopics', 'term' => $topic, 'retmax' => 3,
            ])->throw();

            $xml = $this->xml($response->body());

            foreach ($xml->list->document ?? [] as $document) {
                $fields = [];
                foreach ($document->content as $content) {
                    $fields[(string) $content['name']][] = (string) $content;
                }
                $names = array_map(
                    fn ($v) => strtolower($this->plain($v)),
                    array_merge($fields['title'] ?? [], $fields['altTitle'] ?? [])
                );
                // The search is fuzzy; require the topic in a title so an
                // unrelated page is never offered as a reference.
                if (!collect($names)->contains(fn ($n) => $this->containsPhrase($n, $topic) || $this->containsPhrase($topic, $n))) {
                    continue;
                }

                return [
                    'type'      => 'health_topic',
                    'title'     => $this->plain($fields['title'][0] ?? $topic),
                    'publisher' => 'MedlinePlus, U.S. National Library of Medicine',
                    'url'       => (string) $document['url'],
                    'date'      => null, // not provided by this service
                    'date_kind' => null,
                    'text'      => $this->plain($fields['FullSummary'][0] ?? ''),
                ];
            }

            return null;
        });
    }

    public function whoFactSheet(string $slug): ?array
    {
        return $this->remember("who_{$slug}", function () use ($slug) {
            $url = 'https://www.who.int/news-room/fact-sheets/detail/' . $slug;
            $html = Http::timeout(self::TIMEOUT)->get($url)->throw()->body();

            $dom = new \DOMDocument();
            @$dom->loadHTML('<?xml encoding="utf-8"?>' . $html);
            $xpath = new \DOMXPath($dom);

            $paragraphs = [];
            foreach ($xpath->query('//article//p | //article//li') as $node) {
                $line = $this->plain($node->textContent);
                if (mb_strlen($line) > 30) {
                    $paragraphs[] = $line;
                }
            }
            if (!$paragraphs) {
                throw new \RuntimeException("WHO page layout not recognised: {$slug}");
            }

            preg_match('/class="timestamp">\s*(\d{1,2} [A-Z][a-z]+ \d{4})/', $html, $date);
            preg_match('/<title>\s*(.*?)\s*<\/title>/s', $html, $title);

            return [
                'type'      => 'who_fact_sheet',
                'title'     => 'WHO fact sheet: ' . $this->plain($title[1] ?? $slug),
                'publisher' => 'World Health Organization',
                'url'       => $url,
                'date'      => isset($date[1]) ? Carbon::parse($date[1])->toDateString() : null,
                'date_kind' => 'updated',
                'text'      => implode("\n", array_unique($paragraphs)),
            ];
        });
    }

    /** @return array<int,array<string,mixed>> */
    private function systematicReviews(array $terms): array
    {
        $term = implode(' AND ', array_map(fn ($t) => '"' . $t . '"[Title]', $terms))
            . ' AND (systematic[sb] OR meta-analysis[pt]) AND hasabstract NOT retracted publication[pt]';

        return $this->remember('pubmed_' . md5($term), function () use ($term) {
            $ids = Http::timeout(self::TIMEOUT)->get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi', [
                'db' => 'pubmed', 'retmode' => 'json', 'retmax' => 2, 'sort' => 'relevance', 'term' => $term,
            ])->throw()->json('esearchresult.idlist', []);

            if (!$ids) {
                return [];
            }

            $xml = $this->xml(Http::timeout(self::TIMEOUT)->get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi', [
                'db' => 'pubmed', 'retmode' => 'xml', 'id' => implode(',', $ids),
            ])->throw()->body());

            $reviews = [];
            foreach ($xml->PubmedArticle ?? [] as $article) {
                $citation = $article->MedlineCitation;
                $abstract = [];
                foreach ($citation->Article->Abstract->AbstractText ?? [] as $part) {
                    $abstract[] = dom_import_simplexml($part)->textContent;
                }
                $published = $citation->Article->Journal->JournalIssue->PubDate;
                $year = (string) $published->Year ?: substr((string) $published->MedlineDate, 0, 4);

                $reviews[] = [
                    'type'      => 'systematic_review',
                    'title'     => $this->plain(dom_import_simplexml($citation->Article->ArticleTitle)->textContent),
                    'publisher' => (string) $citation->Article->Journal->Title,
                    'url'       => 'https://pubmed.ncbi.nlm.nih.gov/' . (string) $citation->PMID . '/',
                    'date'      => preg_match('/^\d{4}$/', $year) ? $year : null,
                    'date_kind' => 'published',
                    'text'      => $this->plain(implode(' ', $abstract)),
                ];
            }

            return $reviews;
        }) ?? [];
    }

    /** @return string[] */
    private function whoSlugs(array $terms): array
    {
        $slugs = [];
        foreach (config('evidence.who_fact_sheets', []) as $slug => $phrases) {
            foreach ($terms as $term) {
                foreach ($phrases as $phrase) {
                    if ($this->containsPhrase($term, $phrase)) {
                        $slugs[$slug] = $slug;
                    }
                }
            }
        }

        return array_slice(array_values($slugs), 0, 2);
    }

    private function containsPhrase(string $haystack, string $phrase): bool
    {
        return $phrase !== '' && (bool) preg_match('/\b' . preg_quote($phrase, '/') . '\b/u', $haystack);
    }

    /** Keep the sentences most related to the keywords, in document order. */
    private function selectPassage(string $text, array $keywords): string
    {
        $limit = (int) config('evidence.passage_chars');
        $sentences = preg_split('/(?<=[.!?])\s+|\n+/u', $text, -1, PREG_SPLIT_NO_EMPTY);

        $scores = [];
        foreach ($sentences as $i => $sentence) {
            $lower = mb_strtolower($sentence);
            $scores[$i] = 0;
            foreach ($keywords as $keyword) {
                if (str_contains($lower, $keyword)) {
                    $scores[$i]++;
                }
            }
            if (preg_match('/\b(do not exceed|not to exceed|should not exceed|maximum (recommended |total )?(daily )?dos)/', $lower)) {
                $scores[$i] += 100;
            }
        }
        arsort($scores);

        $chosen = [];
        $length = 0;
        foreach (array_keys($scores) as $i) {
            $size = mb_strlen($sentences[$i]) + 1;
            if ($length + $size > $limit) {
                continue;
            }
            $chosen[$i] = $sentences[$i];
            $length += $size;
        }
        ksort($chosen);

        return $chosen ? implode(' ', $chosen) : mb_substr($text, 0, $limit);
    }

    /** Reduce terms to short plain words so no free text reaches external APIs. */
    private function clean(array $terms): array
    {
        $out = [];
        foreach ($terms as $term) {
            if (!is_string($term)) {
                continue;
            }
            $term = trim(preg_replace('/[^a-z0-9 \-]+/', ' ', strtolower($term)));
            $term = preg_replace('/\s+/', ' ', $term);
            if (strlen($term) >= 3 && strlen($term) <= 60 && substr_count($term, ' ') < 4) {
                $out[$term] = $term;
            }
        }

        return array_values($out);
    }

    private function tier(string $type): int
    {
        return config("evidence.tiers.{$type}", 9);
    }

    private function isStale(string $type, ?string $date): bool
    {
        if (!$date) {
            return false; // unknown age is shown as "date not stated"
        }
        $published = Carbon::parse(strlen($date) === 4 ? "{$date}-01-01" : $date);

        return $published->lt(now()->subDays((int) config("evidence.stale_after_days.{$type}", 1825)));
    }

    private function date(?string $yyyymmdd): ?string
    {
        return $yyyymmdd && preg_match('/^(\d{4})(\d{2})(\d{2})$/', $yyyymmdd, $m) ? "{$m[1]}-{$m[2]}-{$m[3]}" : null;
    }

    private function plain(string $html): string
    {
        $decoded = html_entity_decode($html, ENT_QUOTES | ENT_HTML5, 'UTF-8');
        // A space before each tag keeps adjacent blocks from running together.
        $text = strip_tags(preg_replace('/<(\/?(p|li|ul|ol|br|div|h\d|td|tr)\b)/i', ' <$1', $decoded));
        $text = html_entity_decode($text, ENT_QUOTES | ENT_HTML5, 'UTF-8');
        $text = preg_replace('/[^\S\n]+/u', ' ', $text) ?? $text;

        return trim($text);
    }

    private function xml(string $body): \SimpleXMLElement
    {
        $xml = simplexml_load_string($body, \SimpleXMLElement::class, LIBXML_NONET | LIBXML_NOERROR);
        if ($xml === false) {
            throw new \RuntimeException('Invalid XML response');
        }

        return $xml;
    }

    /** Cache successful lookups, including "nothing found". Errors are not cached. */
    private function remember(string $key, \Closure $callback): mixed
    {
        $boxed = Cache::remember("evidence_src_{$key}", now()->addHours((int) config('evidence.cache_hours')), fn () => [$callback()]);

        return $boxed[0];
    }

    private function safely(string $provider, \Closure $callback): mixed
    {
        try {
            return $callback();
        } catch (\Throwable $e) {
            $this->failures[] = $provider;
            Log::warning("Evidence provider {$provider} failed", ['message' => $e->getMessage()]);

            return null;
        }
    }
}
